#include <stdio.h>

struct Student {
    const char *name;
    int roll;
    float marks;
};

int main() {
    struct Student students[] = {
        {"Ravi", 1, 72.5f},
        {"Meena", 2, 91.0f},
        {"Kiran", 3, 66.5f},
    };
    for (int i = 0; i < 3; i++) {
        printf("%d %s %.1f\n", students[i].roll, students[i].name, students[i].marks);
    }
    return 0;
}
